def intelligent_bacteria(N, M, K, trap_row, trap_col, bacteria_info):
    # Directions represented as (row_change, column_change)
    directions = {'U': (-1, 0), 'R': (0, 1), 'D': (1, 0), 'L': (0, -1)}
    direction_turns = {'U': ['R', 'D', 'L', 'U'], 'R': ['D', 'L', 'U', 'R'], 
                       'D': ['L', 'U', 'R', 'D'], 'L': ['U', 'R', 'D', 'L']}

    # Parse the input for each bacterium
    bacteria = []
    for i in range(K):
        start_row, start_col, direction = bacteria_info[i][:3]
        matrix = bacteria_info[i][3]
        bacteria.append({
            'pos': (start_row - 1, start_col - 1),
            'dir': direction,
            'matrix': matrix
        })

    def turn(bacterium, times):
        index = list(directions.keys()).index(bacterium['dir'])
        new_dir = direction_turns[bacterium['dir']][times % 4]
        bacterium['dir'] = new_dir

    def move(bacterium):
        x, y = bacterium['pos']
        dx, dy = directions[bacterium['dir']]
        return (x + dx, y + dy)

    visited = set()

    def check_bounds(pos):
        x, y = pos
        return 0 <= x < N and 0 <= y < M

    time = 0

    while True:
        time += 1
        new_positions = {}

        for i, bacterium in enumerate(bacteria):
            # Determine how many turns to make
            x, y = bacterium['pos']
            turns = int(bacterium['matrix'][x][y])
            turn(bacterium, turns)

            # Move the bacterium
            new_pos = move(bacterium)

            if not check_bounds(new_pos):
                # Turn 180 degrees if out of bounds
                turn(bacterium, 2)
                new_pos = move(bacterium)

            # Check for traps
            if new_pos == (trap_row - 1, trap_col - 1):
                return time

            # Check for collision
            if new_pos in new_positions:
                new_positions[new_pos].append(i)
            else:
                new_positions[new_pos] = [i]

        # Resolve collisions
        for pos, bacterium_ids in new_positions.items():
            if len(bacterium_ids) > 1:
                return time

        # Update positions
        for pos, bacterium_ids in new_positions.items():
            for i in bacterium_ids:
                bacteria[i]['pos'] = pos

    return -1

