                    turns = bacteria[i][3][x][y]
                    d = turn(d, turns)
                    nx, ny = move(x, y, d)

                    if nx < 0 or nx >= N or ny < 0 or ny >= M:
                        continue

                    new_board[nx][ny].add((i, d))

        board = new_board

        if all(len(cell) == 0 for row in board for cell in row):
            return -1
        if len(board[trap[0]-1][trap[1]-1]) == K:
            return time

