def solve_bacteria_game(N: int, M: int, K: int, trap: Tuple[int, int], bacteria: List[Tuple[int, int, str, List[List[int]]]]) -> int:
    directions = {'U': (-1, 0), 'R': (0, 1), 'D': (1, 0), 'L': (0, -1)}
    turns = {'U': 'R', 'R': 'D', 'D': 'L', 'L': 'U'}

    def next_position(x: int, y: int, direction: str) -> Tuple[int, int]:
        dx, dy = directions[direction]
        return x + dx, y + dy

    def is_outside(x: int, y: int) -> bool:
        return x < 1 or x > N or y < 1 or y > M

    def turn(direction: str, turns: int) -> str:
        for _ in range(turns % 4):
            direction = turns[direction]
        return direction

    positions = [set() for _ in range(K)]
    current_positions = [(x, y, i) for i, (x, y, _, _) in enumerate(bacteria)]

    for second in range(1, 1000001):  # Arbitrary large number
        all_on_trap = True
        new_positions = []

        for i, (x, y, direction, board) in enumerate(bacteria):
            turns_count = board[x-1][y-1]
            new_direction = turn(direction, turns_count)

            if is_outside(x, y):
                new_direction = {'U': 'D', 'R': 'L', 'D': 'U', 'L': 'R'}[new_direction]

            new_x, new_y = next_position(x, y, new_direction)
            new_positions.append((new_x, new_y, i))

            if (new_x, new_y) == trap:
                positions[i].add((new_x, new_y, second))
            else:
                all_on_trap = False

        if all_on_trap:
            return second

        if len(set(new_positions)) != K:
            return -1

        current_positions = new_positions

    return -1

